import java.io.FileReader;

public class Program {
    public static void main(String[] args) {
        try {
            FileReader reader = new FileReader("test.txt");
            System.out.println("File opened");
            reader.close();
        } catch (Exception e) {
            System.out.println("File not found");
        }
    }
}

